def find_lexicographically_smallest_sequence(N, M, edges):
    from collections import defaultdict, deque

    # Create adjacency list and in-degree count
    adj_list = defaultdict(list)
    in_degree = [0] * (N + 1)
    for x, y in edges:
        adj_list[x].append(y)
        in_degree[y] += 1

    # Topological sort to find the order of nodes
    queue = deque([0])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in adj_list[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If there's a cycle, return -1
    if len(order) != N + 1:
        return -1

    # Reconstruct the sequence using the order
    sequence = [0] * (N + 1)
    for i in range(1, N + 1):
        for neighbor in adj_list[order[i - 1]]:
            if sequence[order[i - 1]] + 1 > sequence[neighbor]:
                sequence[neighbor] = sequence[order[i - 1]] + 1

    return sequence[1:]

